package vectors_test

import (
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"github.com/lennylabs/podium/internal/testharness"
	"github.com/lennylabs/podium/pkg/manifest"
)

// tagsFileName is the generated SDK overlay tag corpus, beside this source.
const tagsFileName = "skill-metadata-tags.json"

// tagsDescription is the description member of the generated corpus.
const tagsDescription = "Cross-language corpus for the SDK workspace overlay reading of " +
	"SKILL.md metadata.tags (§4.3.4, §6.4). Generated by " +
	"test/vectors/skill_metadata_tags_test.go; regenerate with UPDATE_GOLDEN=1 go test ./test/vectors/. " +
	"readable is declared from the readable form the TypeScript and Python overlays implement. " +
	"go_tags are the tags manifest.ResolveStoredSkill resolves for skill_md with no ARTIFACT.md, " +
	"null when Go does not parse skill_md. sdk_tags are the tags each SDK overlay must report: " +
	"the declared reading of a readable case and [] for every other case."

// tagsFile is the layout of skill-metadata-tags.json.
type tagsFile struct {
	Description string     `json:"description"`
	Cases       []tagsCase `json:"cases"`
}

// tagsCase is one SKILL.md and the tags Go and the SDKs read from it. GoTags
// is nil, encoded as null, when ResolveStoredSkill returns ok false, and a
// non-nil empty slice when it resolves no tag.
type tagsCase struct {
	Name     string   `json:"name"`
	SkillMD  string   `json:"skill_md"`
	Readable bool     `json:"readable"`
	GoTags   []string `json:"go_tags"`
	SDKTags  []string `json:"sdk_tags"`
}

// tagsForm is a declared case: a SKILL.md, whether the readable form admits
// it, and the form's reading when it does. The readable form and its
// numbered conditions are listed beside metadataTags in
// sdks/podium-ts/src/overlay.ts and _metadata_tags in
// sdks/podium-py/podium/_overlay.py.
type tagsForm struct {
	name     string
	skillMD  string
	readable bool
	reading  []string
}

// skillHead is the name and description every case starts with unless the
// case is about the lines before metadata:.
const skillHead = "name: greet\ndescription: Greet the user politely.\n"

// skillDoc wraps a frontmatter in the --- delimiters and a body.
func skillDoc(frontmatter string) string {
	return "---\n" + frontmatter + "---\nGreet the user by name.\n"
}

// withTags returns a SKILL.md whose metadata block holds block, after the
// standard name and description.
func withTags(block string) string {
	return skillDoc(skillHead + "metadata:\n" + block)
}

// readableForm declares a case the readable form admits, with its reading.
func readableForm(name, skillMD string, tags ...string) tagsForm {
	if tags == nil {
		tags = []string{}
	}
	return tagsForm{name: name, skillMD: skillMD, readable: true, reading: tags}
}

// unreadableForm declares a case outside the readable form.
func unreadableForm(name, skillMD string) tagsForm {
	return tagsForm{name: name, skillMD: skillMD}
}

// readableTagsForms are the cases declared readable, each with its
// declared reading. Each case whose SKILL.md Go parses must resolve to that
// reading.
func readableTagsForms() []tagsForm {
	return []tagsForm{
		readableForm("plain finance close", withTags("  tags: finance, close\n"), "finance", "close"),
		readableForm("plain no space after comma", withTags("  tags: a,b\n"), "a", "b"),
		readableForm("plain punctuation", withTags("  tags: team-a, v1.2, x_y, a/b\n"), "team-a", "v1.2", "x_y", "a/b"),
		readableForm("plain octal-like 010", withTags("  tags: 010\n"), "010"),
		readableForm("plain bool-like true", withTags("  tags: true\n"), "true"),
		readableForm("plain trailing spaces", withTags("  tags: a, b   \n"), "a", "b"),
		readableForm("double-quoted", withTags("  tags: \"finance, close\"\n"), "finance", "close"),
		readableForm("single-quoted", withTags("  tags: 'finance, close'\n"), "finance", "close"),
		readableForm("double-quoted punctuation", withTags("  tags: \"c++, q&a: x # y\"\n"), "c++", "q&a: x # y"),
		readableForm("double-quoted null", withTags("  tags: \"null\"\n"), "null"),
		readableForm("double-quoted tilde", withTags("  tags: \"~\"\n"), "~"),
		// These are readable with the reading []. Condition 7 gives the
		// overlay no tag for an empty element, and §4.3.4 treats an empty
		// tags value as absent, so declaring the empty reading makes the
		// generator check that yaml.v3 and that rule resolve each value to [].
		readableForm("plain empty element", withTags("  tags: a,,b\n")),
		readableForm("double-quoted empty", withTags("  tags: \"\"\n")),
		readableForm("doc example with sensitivity and when_to_use",
			skillDoc("name: run-variance\ndescription: Compare actuals against forecast for a close period.\n"+
				"metadata:\n  version: \"1.0.0\"\n  tags: \"finance, close\"\n  sensitivity: medium\n"+
				"  when_to_use: |\n    After month-end close\n    When reconciling a variance\n"),
			"finance", "close"),
		readableForm("scaffold output without sensitivity",
			withTags("  version: \"1.0.0\"\n  tags: \"finance, close\"\n  when_to_use: |\n    After month-end close\n"),
			"finance", "close"),
		readableForm("tags last frontmatter line", withTags("  owner: alice\n  tags: a, b\n"), "a", "b"),
		readableForm("blank line then sibling", withTags("  tags: a, b\n\n  owner: alice\n"), "a", "b"),
		readableForm("scaffold output with apostrophe in description",
			skillDoc("name: greet\ndescription: Follow the user's guide.\nmetadata:\n  version: \"1.0.0\"\n  tags: \"a, b\"\n"),
			"a", "b"),
		readableForm("single-quoted description holding double quotes",
			skillDoc("name: greet\ndescription: 'say \"hi\"'\nmetadata:\n  tags: a, b\n"), "a", "b"),
		readableForm("block scalar before metadata",
			skillDoc("name: greet\ndescription: |\n  Greet the user\n  politely\nmetadata:\n  tags: a, b\n"), "a", "b"),
		readableForm("crlf line ends",
			strings.ReplaceAll(withTags("  tags: a, b\n"), "\n", "\r\n"), "a", "b"),
		readableForm("merge key after tags", withTags("  tags: a, b\n  <<: {tags: z}\n"), "a", "b"),
		readableForm("document end after tags block", withTags("  tags: a, b\n...\n"), "a", "b"),
		// Go refuses each of these, so go_tags is null.
		readableForm("go refuses sibling sequence after tags", withTags("  tags: a, b\n  owner: [a]\n"), "a", "b"),
		readableForm("go refuses sibling mapping after tags",
			withTags("  tags: a, b\n  build:\n    version: 9.9.9\n"), "a", "b"),
		readableForm("go refuses escaped second tags key", withTags("  tags: a, b\n  \"ta\\x67s\": c\n"), "a", "b"),
	}
}

// unreadableTagsForms are values and layouts outside the readable form. The
// SDK overlays report no tag for each, whatever Go resolves.
func unreadableTagsForms() []tagsForm {
	const owner = "  owner: &k tags\n  tags: a, b\n"
	return []tagsForm{
		unreadableForm("no value", withTags("  tags:\n")),
		unreadableForm("plain tilde", withTags("  tags: ~\n")),
		unreadableForm("plain null", withTags("  tags: null\n")),
		unreadableForm("plain Null", withTags("  tags: Null\n")),
		unreadableForm("plain NULL", withTags("  tags: NULL\n")),
		unreadableForm("plain trailing comment", withTags("  tags: a, b # team\n")),
		unreadableForm("plain tab before comment", withTags("  tags: a, b\t# team\n")),
		unreadableForm("comment as value", withTags("  tags: # team\n")),
		unreadableForm("double-quoted trailing comment", withTags("  tags: \"a, b\" # team\n")),
		unreadableForm("double-quoted escape", withTags("  tags: \"a\\nb\"\n")),
		unreadableForm("single-quoted doubled quote", withTags("  tags: 'it''s'\n")),
		unreadableForm("flow sequence", withTags("  tags: [a, b]\n")),
		unreadableForm("flow mapping", withTags("  tags: {x: y}\n")),
		unreadableForm("mapping value", withTags("  tags: a: b\n")),
		unreadableForm("sequence entry", withTags("  tags: - a\n")),
		unreadableForm("leading dash", withTags("  tags: -a\n")),
		unreadableForm("colon inside", withTags("  tags: a:b\n")),
		unreadableForm("anchor", withTags("  tags: &x a\n")),
		unreadableForm("tag", withTags("  tags: !!str a\n")),
		unreadableForm("folded block", withTags("  tags: >-\n    a, b\n")),
		unreadableForm("literal block", withTags("  tags: |\n    a, b\n")),
		unreadableForm("plain continuation line", withTags("  tags: alpha\n    beta\n")),
		unreadableForm("double-quoted closed on next line", withTags("  tags: \"alpha\n    beta\"\n")),
		unreadableForm("deeper comment after tags", withTags("  tags: a, b\n    # note\n")),
		unreadableForm("child-indent comment after tags", withTags("  tags: a, b\n  # note\n")),
		unreadableForm("two tags lines", withTags("  tags: a, b\n  tags: c\n")),
		unreadableForm("quoted tags key", withTags("  \"tags\": a, b\n")),
		unreadableForm("non-ascii value", withTags("  tags: café\n")),
		unreadableForm("tab after colon", withTags("  tags:\ta, b\n")),
		unreadableForm("tags nested below another child", withTags("  build:\n    tags: a, b\n")),
		unreadableForm("flow-form metadata", skillDoc(skillHead+"metadata: {tags: \"a, b\"}\n")),
		unreadableForm("metadata line with comment", skillDoc(skillHead+"metadata: # info\n  tags: a, b\n")),
		unreadableForm("top-level tags key", skillDoc(skillHead+"tags: a, b\n")),
		unreadableForm("alias key after tags", withTags(owner+"  *k : z\n")),
		unreadableForm("explicit alias key after tags", withTags(owner+"  ? *k\n  : z\n")),
		unreadableForm("explicit key with deeper alias after tags", withTags(owner+"  ?\n    *k\n  : z\n")),
	}
}

// frontmatterTagsForms each hold a tags line that meets conditions 1 to 7,
// in a frontmatter that conditions 8 to 10 or the delimiting rule put outside
// the form.
func frontmatterTagsForms() []tagsForm {
	const tags = "metadata:\n  tags: a, b\n"
	return []tagsForm{
		unreadableForm("single-quoted scalar open across tags", withTags("  owner: 'x\n  tags: a, b\n  y'\n")),
		unreadableForm("double-quoted scalar open across tags", withTags("  owner: \"x\n  tags: a, b\n  y\"\n")),
		unreadableForm("description quoted across metadata",
			skillDoc("name: greet\ndescription: \"foo\n"+tags+"bar\"\n")),
		unreadableForm("anchored description quoted across metadata",
			skillDoc("name: greet\ndescription: &a \"foo\n"+tags+"bar\"\n")),
		unreadableForm("dash line with text before metadata", skillDoc(skillHead+"---x\n"+tags)),
		unreadableForm("dash line with comment before metadata", skillDoc(skillHead+"--- # c\n"+tags)),
		unreadableForm("four dashes before metadata", skillDoc(skillHead+"----\n"+tags)),
		unreadableForm("document end before metadata", skillDoc(skillHead+"...\n"+tags)),
		unreadableForm("indented first line", skillDoc("  name: x\n"+tags)),
		unreadableForm("yaml directive and blank line before metadata", skillDoc(skillHead+"%YAML 1.2\n\n"+tags)),
		unreadableForm("tag directive and comment before metadata",
			skillDoc(skillHead+"%TAG !e! tag:example.com,2000:app/\n# directive\n"+tags)),
		unreadableForm("yaml directive directly before metadata", skillDoc(skillHead+"%YAML 1.2\n"+tags)),
		unreadableForm("sibling sequence before tags", withTags("  owner: [a]\n  tags: a, b\n")),
		unreadableForm("unclosed quote after space in description",
			skillDoc("name: greet\ndescription: say \"hi\n"+tags)),
		unreadableForm("line separator in earlier line",
			skillDoc("name: greet\ndescription: foo\u2028  bar\n"+tags)),
		unreadableForm("lone cr in description", skillDoc("name: greet\ndescription: foo\r  bar\n"+tags)),
		unreadableForm("lone cr between keys", skillDoc("name: greet\rx: y\n"+tags)),
	}
}

// TestSkillMetadataTagsVectors_MatchGo builds every corpus case, resolves its
// SKILL.md through manifest.ResolveStoredSkill, fails when a readable case
// that Go parses resolves to tags other than its declared reading, and
// compares the generated corpus with test/vectors/skill-metadata-tags.json.
//
// Spec: §4.3.4
// Spec: §6.4
func TestSkillMetadataTagsVectors_MatchGo(t *testing.T) {
	t.Parallel()
	var forms []tagsForm
	forms = append(forms, readableTagsForms()...)
	forms = append(forms, unreadableTagsForms()...)
	forms = append(forms, frontmatterTagsForms()...)
	cases := make([]tagsCase, 0, len(forms))
	names := make([]string, 0, len(forms))
	for _, f := range forms {
		cases = append(cases, tagsCaseOf(t, f))
		names = append(names, f.name)
	}
	checkUniqueNames(t, "skill metadata tags", names)
	if t.Failed() {
		return
	}
	file := tagsFile{
		Description: tagsDescription,
		Cases:       sortByName(cases, func(c tagsCase) string { return c.Name }),
	}
	testharness.AssertGoldenFile(t, filepath.Join(".", tagsFileName), encodeVectors(t, file))
}

// tagsCaseOf resolves one declared form and checks a readable form's reading
// against Go. A readable form Go does not parse falls outside the §4.3.4
// overlay invariant, which covers only a frontmatter that decodes.
func tagsCaseOf(t testing.TB, f tagsForm) tagsCase {
	t.Helper()
	c := tagsCase{Name: f.name, SkillMD: f.skillMD, Readable: f.readable, SDKTags: []string{}}
	if f.readable {
		c.SDKTags = f.reading
	}
	a, _, _, ok := manifest.ResolveStoredSkill(nil, []byte(f.skillMD))
	if !ok {
		return c
	}
	c.GoTags = append([]string{}, a.Tags...)
	if f.readable && !reflect.DeepEqual(c.GoTags, f.reading) {
		t.Errorf("%s: Go resolves tags %q, but the readable form declares %q", f.name, c.GoTags, f.reading)
	}
	return c
}
